Bash(cd /tmp && cat > pixcheck.go <<'EOF'
package main

import \(
	"fmt"
	"image/png"
	"os"
\)

func main\(\) {
	for _, f := range []string{"/tmp/jb-tabs.png", "/tmp/jb-tabs-hover.png", "/tmp/jb-editor.png"} {
		fh, err := os.Open\(f\)
		if err != nil {
			fmt.Println\(err\)
			continue
		}
		img, err := png.Decode\(fh\)
		fh.Close\(\)
		if err != nil {
			fmt.Println\(err\)
			continue
		}
		b := img.Bounds\(\)
		fmt.Printf\("== %s %dx%d\\n", f, b.Dx\(\), b.Dy\(\)\)
		at := func\(x, y int\) {
			r, g, bl, a := img.At\(x, y\).RGBA\(\)
			fmt.Printf\("  \(%d,%d\) #%02X%02X%02X a=%02X\\n", x, y, r>>8, g>>8, bl>>8, a>>8\)
		}
		at\(10, 5\)   // tab bar background \(left of first tab\)
		at\(100, 5\)  // active tab area \(main.go, above text\)
		at\(100, 33\) // active tab bottom indicator
		at\(300, 5\)  // inactive tab area \(server.go\)
		at\(380, 5\)  // inactive tab area \(go.mod\)
	}
}
EOF
go run pixcheck.go)
